namespace EnterpriseDocumentIntelligence.ProcessingService.Domain;
public sealed record TextChunk(Guid DocumentId,int Number,string Text,int TokenCount);
public sealed class ProcessingDocument(Guid documentId,string tenantId,string text){ public Guid DocumentId{get;}=documentId; public string TenantId{get;}=string.IsNullOrWhiteSpace(tenantId)?throw new ArgumentException("Tenant is required.",nameof(tenantId)):tenantId; public string Text{get;}=text??throw new ArgumentNullException(nameof(text)); public IReadOnlyList<TextChunk> CreateChunks(int maxCharacters=2000){if(maxCharacters<=0)throw new ArgumentOutOfRangeException(nameof(maxCharacters));if(string.IsNullOrWhiteSpace(Text))return [];var result=new List<TextChunk>();for(var offset=0;offset<Text.Length;offset+=maxCharacters){var chunk=Text.Substring(offset,Math.Min(maxCharacters,Text.Length-offset)).Trim();if(chunk.Length>0)result.Add(new TextChunk(DocumentId,result.Count,chunk,chunk.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries).Length));}return result;} }